import { tags } from "typia";

/**
 * High-level aggregate payment metrics for a given analysis window.
 *
 * These KPIs typically appear at the top of an analytics dashboard to provide a
 * quick overview of payment performance.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallAnalyticsPaymentTotals = {
  /**
   * Total monetary amount successfully processed in the analysis window,
   * expressed in the platform's base currency or a normalized currency used
   * for analytics.
   */
  totalProcessedAmount: number;

  /**
   * Total number of logical payments processed in the analysis window,
   * regardless of status.
   */
  totalPayments: number & tags.Type<"int32">;

  /**
   * Number of logical payments that reached a successful terminal status
   * (e.g., captured or succeeded).
   */
  successfulPayments: number & tags.Type<"int32">;

  /** Number of logical payments that reached a failure terminal status. */
  failedPayments: number & tags.Type<"int32">;

  /**
   * Total monetary amount refunded within the analysis window, regardless of
   * when the original payments occurred.
   */
  refundedAmount?: number | undefined;

  /**
   * Total monetary amount associated with chargebacks within the analysis
   * window.
   */
  chargebackAmount?: number | undefined;

  /** Average processed amount per successful payment in the analysis window. */
  averageTicketSize?: number | undefined;
};
